package com.amr.pages;
import org.openqa.selenium.*;import org.openqa.selenium.support.ui.*;import java.time.Duration;
public class BasePage {protected final WebDriver driver;protected final WebDriverWait wait;public BasePage(WebDriver driver){this.driver=driver;wait=new WebDriverWait(driver,Duration.ofSeconds(10));}protected void click(By by){wait.until(ExpectedConditions.elementToBeClickable(by)).click();}protected void type(By by,String value){WebElement e=wait.until(ExpectedConditions.visibilityOfElementLocated(by));e.clear();e.sendKeys(value);}protected String getText(By by){return wait.until(ExpectedConditions.visibilityOfElementLocated(by)).getText();}protected boolean isDisplayed(By by){try{return wait.until(ExpectedConditions.visibilityOfElementLocated(by)).isDisplayed();}catch(TimeoutException e){return false;}}}
